function shortDate(value) {
  if (!value) return '尚未检查';
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? String(value) : new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Shanghai',hour12:false}).format(d);
}
function readActionState(){try{return JSON.parse(localStorage.getItem(taskStateKey)||'{}')}catch{return {}}}
function setActionState(id,done){try{const state=readActionState();state[id]=done;localStorage.setItem(taskStateKey,JSON.stringify(state));return true}catch{return false}}
function downloadCSV(name,rows){
  const csv='\ufeff'+rows.map(row=>row.map(cell=>'"'+String(cell??'').replace(/^[=+@-]/,m=>"'"+m).replace(/"/g,'""')+'"').join(',')).join('\r\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
  const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
