function actionCard(item,index){return '<article class="action-card"><div class="action-meta"><span>0'+(index+1)+' / '+item.owner+'</span><span>'+item.time+'</span></div><h2>'+item.title+'</h2><p>'+item.summary+'</p><div class="action-outcome">'+item.outcome+'</div><a class="action-link" href="#'+item.link+'">'+item.cta+' <span>↗</span></a></article>'}
function sourceList(){return Array.isArray(watchData?.sources)?watchData.sources:[]}
