function focusQuotes(){return ['116-01','116-05','116-07'].map(id=>records.find(r=>r.id===id&&r.origin==='round6')).filter(Boolean)}
function watchMini(){const sources=sourceList(),good=sources.filter(sourceIsGood);return '<section class="watch-mini"><div><span class="eyebrow">持续跟踪</span><h2>变化值得看，依据查得到</h2><p>固定公开来源每 6 小时计划检查；跨来源 AI 检索每日复核。新证据经过筛选，再进入行动建议。</p></div><div class="watch-facts"><div><strong>'+good.length+' / '+sources.length+'</strong><span>最近成功检查的来源</span></div><div><strong>'+changesList().length+'</strong><span>记录的正文变化 · 待判断影响</span></div><div><strong class="time-value">'+escapeHtml(shortDate(watchData?.checked_at||watchData?.generated_at))+'</strong><span>最近检查 · 北京时间</span></div></div><a class="action-link" href="#watch">查看监测记录与边界 ↗</a></section>'}
