products=function(){
  main.className='decision-page';
  main.innerHTML=briefIntro('把采购价，算到同一口径','下面是三条询价线索。先核到店成本，再讨论价格空间；公开挂牌价不直接作为下单依据。','EVERY MART / PROCUREMENT')+
    '<div class="quick-tools"><button class="btn primary" data-scroll-to="landed-cost-form">计算到店成本 ↓</button><button class="btn" data-download="inquiry">领取询价单</button><a href="data/116-prices.csv" download>4 条公开报价 CSV ↓</a></div><div class="quote-grid">'+focusQuotes().map(o=>'<article class="quote-card"><span class="tag">公开箱价 · 待核到店</span><h2>'+escapeHtml(o.sku)+'</h2><p class="quote-spec">'+escapeHtml(o.spec)+'</p><div class="quote-price">'+fmt(o.raw_price)+'<small>'+escapeHtml(o.raw_unit)+'</small></div><p class="quote-supplier">'+escapeHtml(o.supplier)+'</p><dl class="quote-terms"><dt>起订</dt><dd>'+escapeHtml(o.moq||'未明示')+'</dd><dt>需核</dt><dd>'+escapeHtml(o.conditions)+'</dd><dt>有效期</dt><dd>来源未明示；'+escapeHtml(o.collected_at)+'采集</dd></dl><button class="action-link" data-key="'+escapeHtml(keyOf(o))+'">查看原始证据 ↗</button></article>').join('')+'</div>'+
    '<div class="procurement-grid"><section class="tool-panel"><div class="section-head"><div><span class="eyebrow">填写后即可测算</span><h2>这张报价，到店每件多少钱？</h2></div></div><p class="tool-note">输入供应商本次报价。所有费用采用相同税务口径，未兑现返利不先扣除。</p><form id="landed-cost-form"><div class="form-grid">'+[['goods','货款合计（元）','例如 980'],['freight','运费及其他费用（元）','请填写，免运填 0'],['discount','已确认折让（元）','无折让填 0'],['units','可售总件数（件）','例如 300'],['current','现行到店单价（元，可选）','用于比较价差'],['selling','拟售单价（元，可选）','用于测算商品毛利']].map(([id,label,placeholder])=>'<label>'+label+'<input id="cost-'+id+'" type="number" min="0" step="'+(id==='units'?'1':'0.01')+'" inputmode="decimal" placeholder="'+placeholder+'"></label>').join('')+'</div><div id="cost-output" class="cost-output" aria-live="polite">填写货款、费用、折让和可售件数后显示结果。</div><button class="btn" type="button" id="download-cost">下载本次测算</button><span id="cost-download-status" class="small" role="status"></span></form></section><section class="tool-panel inquiry-panel"><span class="eyebrow">采购准备</span><h2>发给供应商的六个问题</h2><ol><li>条码、口味和箱规是否完全一致？</li><li>到成都门店的含税价、运费是多少？</li><li>最低起订量和交期分别是多少？</li><li>到货剩余保质期与临期退换规则？</li><li>现金、账期和返利是否影响价格？</li><li>报价有效到哪一天，能否书面确认？</li></ol><button class="btn primary" data-download="inquiry">下载供应商询价单</button><p class="small">已填三条商品规格；有效报价栏留空，供实际询价后回填。</p><a class="action-link" href="#database">搜索其他商品与来源 ↗</a></section></div>';
  document.getElementById('landed-cost-form').addEventListener('submit',e=>e.preventDefault());
  document.querySelectorAll('#landed-cost-form input').forEach(input=>input.addEventListener('input',updateCost));
  document.getElementById('download-cost').onclick=()=>{const result=costResult();if(result.error){document.getElementById('cost-download-status').textContent=result.error;return}downloadCSV('集刻-采购到店成本测算.csv',[['字段','数值','说明'],...Object.entries(result.values).map(([k,v])=>[k,v,'用户输入']),['到店单价',result.unit.toFixed(4),'同税务口径；非供应商承诺'],['与现行价差',result.delta==null?'':result.delta.toFixed(4),'正数表示新报价更低；尚未计入换供风险'],['商品毛利率',result.margin==null?'':(result.margin*100).toFixed(2)+'%','未扣报损、租金、人工与平台费用']]);document.getElementById('cost-download-status').textContent='已生成测算文件。'};
};
function costResult(){
  const keys=['goods','freight','discount','units','current','selling'];const v=Object.fromEntries(keys.map(k=>[k,document.getElementById('cost-'+k)?.value??'']));
  if(keys.slice(0,4).some(k=>v[k]===''))return {error:'请填写货款、费用、折让和可售件数；没有费用或折让请填 0。'};
  if(keys.some(k=>v[k]!==''&&(!Number.isFinite(Number(v[k]))||Number(v[k])<0)))return {error:'请填写有效的非负数字。'};
  const n=Object.fromEntries(keys.map(k=>[k,v[k]===''?null:Number(v[k])]));
  if(!Number.isInteger(n.units)||n.units<=0||n.discount>n.goods+n.freight)return {error:'可售件数须为正整数，折让不能高于货款与费用合计。'};
  if(n.selling===0)return {error:'拟售单价须大于 0，或留空不测算毛利。'};
  const unit=(n.goods+n.freight-n.discount)/n.units;
  if(!Number.isFinite(unit)||unit>1e12)return {error:'金额超出可计算范围，请检查输入。'};
  return {unit,delta:n.current==null?null:n.current-unit,margin:n.selling==null?null:(n.selling-unit)/n.selling,values:{'货款':n.goods,'费用':n.freight,'折让':n.discount,'件数':n.units,'现行到店单价':n.current,'拟售单价':n.selling}};
}
function updateCost(){const r=costResult();document.getElementById('cost-output').innerHTML=r.error?escapeHtml(r.error):'<span>到店单价</span><strong>¥ '+fmt(r.unit)+' <small>/ 件</small></strong>'+(r.delta!=null?'<p>较现行单价'+(r.delta>=0?'低 ':'高 ')+'¥ '+fmt(Math.abs(r.delta))+' / 件</p>':'')+(r.margin!=null?'<p>商品毛利率测算 '+(r.margin*100).toFixed(1)+'% · 未扣经营费用与报损</p>':'')+'<small>以上仅为所填条件的测算，确认供货、有效期和品质后再决策。</small>'}
